<?php
declare(strict_types=1);
require_once __DIR__ . '/../config/app.php'; require_once __DIR__ . '/../includes/referral_opportunities.php';
$user=require_login('BUSINESS'); $businessId=(int)$user['id'];
if($_SERVER['REQUEST_METHOD']==='POST'){try{verify_csrf();$id=filter_input(INPUT_POST,'id',FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);$action=(string)($_POST['action']??'');if(!$id||!in_array($action,['deactivate','delete'],true))throw new RuntimeException('The requested action is invalid.');$stmt=db()->prepare($action==='delete'?'DELETE FROM referral_opportunities WHERE id=? AND business_id=?':'UPDATE referral_opportunities SET status=\'Inactive\' WHERE id=? AND business_id=?');$stmt->execute([$id,$businessId]);if(!$stmt->rowCount())throw new RuntimeException('Referral opportunity was not found or could not be updated.');ActivityLogService::logActivity($businessId,'BUSINESS','Business',$action==='delete'?'Opportunity Deleted':'Opportunity Updated','Opportunity',$id,$action==='delete'?'Opportunity deleted.':'Opportunity deactivated.');set_flash('success',$action==='delete'?'Referral opportunity deleted.':'Referral opportunity deactivated.');}catch(Throwable $e){app_log('Opportunity action failed: '.$e->getMessage());set_flash('danger',$e instanceof RuntimeException?$e->getMessage():'We could not update that opportunity.');}redirect('business/opportunities.php');}
$search=mb_substr(trim((string)($_GET['search']??'')),0,100);$category=mb_substr(trim((string)($_GET['category']??'')),0,100);$status=in_array($_GET['status']??'',REFERRAL_OPPORTUNITY_STATUSES,true)?(string)$_GET['status']:'';$product=mb_substr(trim((string)($_GET['product']??'')),0,150);$page=max(1,(int)($_GET['page']??1));$perPage=20;$where=['o.business_id=?'];$params=[$businessId];
if($search!==''){$where[]='o.title LIKE ?';$params[]='%'.$search.'%';}if($category!==''){$where[]='o.category=?';$params[]=$category;}if($status!==''){$where[]='o.status=?';$params[]=$status;}if($product!==''){$where[]='EXISTS (SELECT 1 FROM opportunity_products p WHERE p.opportunity_id=o.id AND p.product_name=?)';$params[]=$product;}$whereSql=implode(' AND ',$where);$count=db()->prepare("SELECT COUNT(*) FROM referral_opportunities o WHERE {$whereSql}");$count->execute($params);$total=(int)$count->fetchColumn();$page=min($page,max(1,(int)ceil($total/$perPage)));$stmt=db()->prepare("SELECT o.*, (SELECT COUNT(*) FROM opportunity_products p WHERE p.opportunity_id=o.id) AS product_count FROM referral_opportunities o WHERE {$whereSql} ORDER BY o.created_at DESC LIMIT {$perPage} OFFSET ".(($page-1)*$perPage));$stmt->execute($params);$opportunities=$stmt->fetchAll();
$categories=db()->prepare('SELECT DISTINCT category FROM referral_opportunities WHERE business_id=? ORDER BY category');$categories->execute([$businessId]);$products=db()->prepare('SELECT DISTINCT p.product_name FROM opportunity_products p JOIN referral_opportunities o ON o.id=p.opportunity_id WHERE o.business_id=? ORDER BY p.product_name');$products->execute([$businessId]);$stats=business_opportunity_stats($businessId);$query=static function(array $changes=[])use($search,$category,$status,$product){return http_build_query(array_filter(array_merge(compact('search','category','status','product'),$changes),static fn($v)=>$v!==''&&$v!==null));};$pageTitle='My referral opportunities | '.APP_NAME;require_once __DIR__.'/../includes/header.php';
?>
<main class="opportunity-page"><div class="container py-5"><div class="opportunity-hero"><div><span class="eyebrow"><i class="bi bi-megaphone"></i> Business workspace</span><h1>My referral opportunities</h1><p>Search and filter your campaigns by title, category, status, or product.</p></div><a class="btn btn-primary" href="<?=e(url('business/opportunity_form.php'))?>"><i class="bi bi-plus-lg"></i> Create referral opportunity</a></div><div class="row g-3 mt-1"><?php foreach([['Total opportunities',$stats['total'],'bi-grid-1x2'],['Active opportunities',$stats['active'],'bi-broadcast'],['Inactive opportunities',$stats['inactive'],'bi-pause-circle']]as[$label,$value,$icon]):?><div class="col-6 col-lg-4"><section class="stat-card"><i class="bi <?=e($icon)?>"></i><span><?=e($label)?></span><strong><?=$value?></strong></section></div><?php endforeach;?></div><section class="opportunity-list-card mt-4"><div class="list-card-heading"><div><h2>Opportunities</h2><p><?=$total?> result<?=$total===1?'':'s'?> found</p></div></div><form class="row g-3 filter-panel" method="get"><div class="col-lg-4"><input class="form-control" name="search" value="<?=e($search)?>" placeholder="Search campaign title" data-instant-search></div><div class="col-sm-6 col-lg-2"><select class="form-select" name="category"><option value="">All categories</option><?php foreach($categories->fetchAll(PDO::FETCH_COLUMN)as$item):?><option <?=$category===$item?'selected':''?>><?=e($item)?></option><?php endforeach;?></select></div><div class="col-sm-6 col-lg-2"><select class="form-select" name="status"><option value="">Active / inactive</option><?php foreach(REFERRAL_OPPORTUNITY_STATUSES as$item):?><option <?=$status===$item?'selected':''?>><?=e($item)?></option><?php endforeach;?></select></div><div class="col-sm-6 col-lg-2"><select class="form-select" name="product"><option value="">All products</option><?php foreach($products->fetchAll(PDO::FETCH_COLUMN)as$item):?><option <?=$product===$item?'selected':''?>><?=e($item)?></option><?php endforeach;?></select></div><div class="col-sm-6 col-lg-2 d-flex gap-2"><button class="btn btn-outline-primary flex-grow-1">Apply</button><a class="btn btn-light border" href="<?=e(url('business/opportunities.php'))?>">Clear</a></div></form><?php if(!$opportunities):?><div class="empty-state"><span><i class="bi bi-inbox"></i></span><h3>No opportunities found</h3><p>Try clearing or adjusting the filters.</p></div><?php else:?><div class="table-responsive"><table class="table opportunity-table align-middle"><thead><tr><th>Title</th><th>Category</th><th>Products</th><th>Location</th><th>Status</th><th>Expiry date</th><th class="text-end">Actions</th></tr></thead><tbody><?php foreach($opportunities as$opportunity):?><tr><td><strong><?=e($opportunity['title'])?></strong></td><td><?=e($opportunity['category'])?></td><td><?= (int)$opportunity['product_count']?></td><td><?=e($opportunity['service_location'])?></td><td><span class="opportunity-status <?=strtolower(e($opportunity['status']))?>"><?=e($opportunity['status'])?></span></td><td><?=e(date('d M Y',strtotime($opportunity['valid_until'])))?></td><td><div class="table-actions justify-content-lg-end"><a class="btn btn-sm btn-light border" href="<?=e(url('business/opportunity_view.php?id='.$opportunity['id']))?>">View</a><a class="btn btn-sm btn-light border" href="<?=e(url('business/opportunity_form.php?id='.$opportunity['id']))?>">Edit</a><?php if($opportunity['status']==='Active'):?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?= (int)$opportunity['id']?>"><input type="hidden" name="action" value="deactivate"><button class="btn btn-sm btn-light border">Deactivate</button></form><?php endif;?><form method="post" data-confirm="Delete this referral opportunity? This cannot be undone."><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?= (int)$opportunity['id']?>"><input type="hidden" name="action" value="delete"><button class="btn btn-sm btn-outline-danger">Delete</button></form></div></td></tr><?php endforeach;?></tbody></table></div><?php endif;?><?php if($total>$perPage):?><nav class="mt-3"><ul class="pagination justify-content-end mb-0"><?php for($p=1;$p<=ceil($total/$perPage);$p++):?><li class="page-item <?=$p===$page?'active':''?>"><a class="page-link" href="<?=e(url('business/opportunities.php?'.$query(['page'=>$p])))?>"><?=$p?></a></li><?php endfor;?></ul></nav><?php endif;?></section></div></main>
